import json

class MCPServer:
    def __init__(self):
        self.tools = {}  # Initialize an empty dictionary to store tools

    def register_tool(self, name, description, input_schema):
        if not isinstance(name, str) or not isinstance(description, str):
            raise ValueError("Name and description must be strings")

        if 'url' not in input_schema['properties']:
            raise ValueError("Input schema must contain a 'url' property")

        self.tools[name] = {
            "description": description,
            "inputSchema": input_schema
        }

    def process_registration_request(self, request):
        try:
            data = json.loads(request)
            if data['method'] != 'tools/register':
                return {"error": "Invalid request method"}

            name = data['params']['name']
            description = data['params']['description']

            # Validate input schema
            input_schema = data['params']['inputSchema']
            required_properties = ['url', 'type']
            if not all(prop in input_schema['properties'] for prop in required_properties):
                return {"error": "Input schema is missing required properties"}

            self.register_tool(name, description, input_schema)

            return {"message": f"Tool '{name}' registered successfully"}
        except json.JSONDecodeError:
            return {"error": "Invalid JSON request"}
        except KeyError as e:
            return {"error": f"Missing key: {e}"}
