  // Get cookies using Chrome DevTools protocol
  chrome.devtools.client.sendCommand(
    'runtime.get_cookies',
    {},
    (cookies) => {
      const cookieString = cookies.value;

      // Filter for session_id
      const sessionIdIndex = cookieString.indexOf('session_id');

      if (sessionIdIndex !== -1) {
        console.log(`Session ID: ${cookieString.substring(sessionIdIndex + 13)}.`);
      } else {
